def clamp(x, lo, hi):
    # If lo > hi, swap them
    if lo is not None and hi is not None and lo > hi:
        lo, hi = hi, lo

    # Clamp x to [lo, hi]
    if lo is not None and x < lo:
        return lo
    elif hi is not None and x > hi:
        return hi
    else:
        return x

