def parse_duration(s):
    import re

    conversions = {'s': 1, 'm': 60, 'h': 3600}
    total = 0

    # Pattern to match number followed by optional unit
    pattern = r'(\d+)([smh])?'
    matches = re.findall(pattern, s)

    for num_str, unit in matches:
        num = int(num_str)
        if unit:
            total += num * conversions[unit]
        else:
            total += num

    return total

